4	export class Clubspot {
5	  private _user!: Parse.User;
6	  public get user() {
7	    return this._user;
8	  }
9	
10	  /**
11	   * Initializes the Parse SDK to the main Clubspot API and logins with the
12	   * supplied email address and password.
13	   */
14	  public async initialize(email: string, password: string) {
15	    const serverUrl = "https://theclubspot.com/parse";
16	    const applicationId = "myclubspot2017";
17	
18	    Parse.CoreManager.set("SERVER_URL", serverUrl);
19	    Parse.initialize(applicationId);
20	    winston.debug("Parse initialized", { serverUrl, applicationId });
21	
22	    const users = await this.retrieveUsersByEmail(email);
23	
24	    if (users.length < 1) {
25	      throw new Error(`No user found with email address: ${email}`);
26	    }
27	
28	    const user = users[0] as Parse.User;
29	    const username = user.getUsername();
30	    winston.debug("Logging into Clubspot", { email, username });
31	
32	    // If this is not enabled, the current user is NOT stored in memory, and all future calls to parse are unauthenticated.
33	    // TODO: This would be more secure with a wrapper around Parse
34	    winston.warn("Enabling unsafe current user on Parse-SDK-JS");
35	    Parse.User.enableUnsafeCurrentUser();
36	    this._user = await Parse.User.logIn(username!, password);
37	  }
38	
39	  /**
40	   * Retrieves a list of users registered with the given email address.
41	   * TODO: Add mobile phone lookup?
42	   */
43	  public retrieveUsersByEmail(email: string): Promise<Parse.User[]> {
44	    return Parse.Cloud.run("retrieveUsersByEmailOrMobileNumber", {
45	      email: email,
46	    });
47	  }
48	}
