1	/**
2	 * Typescript Wrappers around the Parse Javascript SDK.
3	 * @see https://parseplatform.org/Parse-SDK-JS/api/5.3.0/
4	 */
5	import Parse from "parse/node.js";
6	import winston from "winston";
7	export { Parse };
8	
9	export type ObjectConstructor<T> = { new (options?: any): T };
10	
11	interface Schema<T> {
12	  objectClass: string;
13	  className: string;
14	  clazz: ObjectConstructor<T>;
15	}
16	
17	/**
18	 * A list of all Parse classes that have been registered.
19	 */
20	export const schemas: Schema<any>[] = [];
21	
22	/**
23	 * Registers a subclass of Parse.Object with Parse. Requires that objectClass be a static property of the class.
24	 */
25	export function register<T extends Parse.Object>(clazz: ObjectConstructor<T>, context: ClassDecoratorContext): void {
26	  context.addInitializer(() => {
27	    const objectClass = (clazz as any)["objectClass"] as string;
28	    if (objectClass === undefined) {
29	      throw TypeError("objectClass must be defined on Parse.Objects");
30	    }
31	
32	    const className = context.name!;
33	
34	    schemas.push({ objectClass, className, clazz });
35	    Parse.Object.registerSubclass(objectClass, clazz);
36	  });
37	}
38	
39	/**
40	 * A simple wrapper around query that logs to winston before any finalizer method is called.
41	 */
42	export class LoggedQuery<T extends Parse.Object> extends Parse.Query<T> {
43	  override find(options?: Parse.Query.FindOptions): Promise<T[]> {
44	    winston.debug("Executing Query:find", {
45	      objectClass: this.objectClass,
46	      query: this.toJSON(),
47	      options,
48	    });
49	    return super.find(options);
50	  }
51	
52	  override get(objectId: string, options?: Parse.Query.GetOptions): Promise<T> {
53	    winston.debug("Executing Query:get", {
54	      objectClass: this.objectClass,
55	      objectId,
56	      options,
57	    });
58	    return super.get(objectId, options);
59	  }
60	}
