3	import { Command, InvalidArgumentError, Option } from "@commander-js/extra-typings";
4	import { Clubspot } from "../src/clubspot.js";
5	import winston from "winston";
6	import { LoggedQuery, schemas } from "./parse.js";
7	import { Club, UserClub } from "./types.js";
8	import { ClubspotPasswordOption, ClubspotUsernameOption } from "./options.js";
9	import { OutputOption, LoggingOption, VerboseOption } from "@cyc-seattle/commodore";
10	
11	function parseIntOption(value: string) {
12	  const parsed = parseInt(value);
13	  if (isNaN(parsed)) {
14	    throw new InvalidArgumentError("Not a number");
15	  }
16	  return parsed;
17	}
18	
19	interface Filter {
20	  attribute: string;
21	  value: string;
22	}
23	
24	/**
25	 * TODO Support more complicated filters. I don't like this simple parsing.
26	 */
27	function parseFilterOption(value: string, previous: Filter[]) {
28	  const parsed = value.split("=");
29	  if (parsed.length != 2) {
30	    throw new InvalidArgumentError("Expected format: <attribute>=<value>");
31	  }
32	
33	  const filter: Filter = {
34	    attribute: parsed[0]!,
35	    value: parsed[1]!,
36	  };
37	
38	  return previous.concat([filter]);
39	}
40	
41	function getClub(clubId: string): Promise<Club> {
42	  try {
43	    return new LoggedQuery(Club).get(clubId);
44	  } catch {
45	    throw new InvalidArgumentError(`No club with id ${clubId} exists.`);
46	  }
47	}
48	
49	const clubspot = new Clubspot();
50	
51	// A separate logger to use for the output of commands.  Writes to stdout.
52	// This outputLogger will get overwritten by a fully configured logger during the preAction hook.
53	let outputLogger = winston.child({});
54	
55	const program = new Command("clubspot")
56	  .addOption(new ClubspotUsernameOption())
57	  .addOption(new ClubspotPasswordOption())
58	  .addOption(new OutputOption())
59	  .addOption(new LoggingOption())
60	  .addOption(new VerboseOption())
61	  .hook("preAction", async (command, action) => {
62	    const opts = command.opts();
63	
64	    winston.configure({
65	      level: opts.verbose ?? "warn",
66	      format: opts.logging,
67	      transports: new winston.transports.Stream({ stream: process.stderr }),
68	    });
69	
70	    outputLogger = winston.createLogger({
71	      level: "info",
72	      format: opts.format,
73	      transports: new winston.transports.Console(),
74	    });
75	
76	    await clubspot.initialize(opts.username, opts.password);
77	
78	    winston.debug("Executing action", {
79	      action: action.args.join(" "),
80	      options: action.opts(),
81	    });
82	  });
83	
84	program
85	  .command("whoami")
86	  .description("Lookup your Clubspot user information and what clubs you are assigned to.")
87	  .alias("who")
88	  .action(async () => {
89	    const query = new LoggedQuery(UserClub).include("clubObject").equalTo("userObject", clubspot.user);
90	
91	    const results = await query.find();
92	
93	    const clubs = results.map((userClub) => {
94	      const club = userClub.get("clubObject");
95	      return {
96	        id: club.id,
97	        name: club.get("name"),
98	        admin: userClub.get("admin"),
99	        manager: userClub.get("manager"),
100	        permissions: userClub.get("permissions"),
101	      };
102	    });
103	
104	    outputLogger.info({
105	      user: clubspot.user.toJSON(),
106	      clubs,
107	    });
108	  });
109	
110	for (const schema of schemas) {
111	  const subcommand = program.command(schema.objectClass);
112	  const query = new LoggedQuery(schema.objectClass);
113	
114	  subcommand
115	    .command("get <id>")
116	    .option("--include <attributes...>", "Attributes to include in the returned result.")
117	    .action(async (objectId, options) => {
118	      if (options.include) {
119	        query.include(...options.include);
120	      }
121	
122	      const result = await query.get(objectId);
123	      outputLogger.info(result.toJSON());
124	    });
125	
126	  // TODO: .addOption(super("--club <id>", "The id of the Clubspot club to limit results to.");
127	  subcommand
128	    .command("list")
129	    .alias("ls")
130	    .addOption(new Option("-c, --club <id>").env("CLUBSPOT_CLUB_ID").makeOptionMandatory())
131	    .option("--limit <number>", "The number of results to return.", parseIntOption, 10)
132	    .option("--include <attributes...>", "Attributes to include in the returned result.")
133	    .option(
134	      "--sort <attributes...>",
135	      'Repeatable list of attributes to sort by. Default ascending, start with "-" if you want descending.',
136	    )
137	    .option(
138	      "--filter <attribute>=<value>",
139	      "Filters the results where attribute == value. Repeatable",
140	      parseFilterOption,
141	      [],
142	    )
143	    .action(async (options) => {
144	      // TODO: Not every class is filtered on clubObject.
145	      const club = await getClub(options.club);
146	      query.include("clubObject").equalTo("clubObject", club);
147	
148	      query.limit(options.limit);
149	
150	      if (options.include) {
151	        query.include(...options.include);
152	      }
153	
154	      for (const filter of options.filter) {
155	        query.equalTo(filter.attribute, filter.value);
156	      }
157	
158	      for (const sortClause of options.sort ?? []) {
159	        if (sortClause.startsWith("-")) {
160	          query.addDescending(sortClause.substring(1));
161	        } else {
162	          query.addAscending(sortClause);
163	        }
164	      }
165	
166	      const results = await query.find();
167	      const mapped = results.map((result) => result.toJSON());
168	      outputLogger.info(mapped);
169	    });
170	}
171	
172	await program.parseAsync();
